insert into public.works (id, title, kind, description, people, region, period, museum, city, address, image_url, link, source, published, sort) values
  ('cma-146110', 'Couple de statuettes asye usu', 'Statue', 'Chez les Baoulé, les statuettes sculptées par paires représentent souvent les asye usu, des esprits de la brousse qui peuvent entrer dans la vie d''une personne. Celle-ci peut alors devenir devin et, en transe, révéler la cause des maladies et des malheurs. On commande ces figures d''homme et de femme, belles et soigneusement parées, pour séduire les esprits et les inviter à y demeurer. Les coiffures reprennent celles que l''on portait à l''époque de la sculpture. Bois, résine, perles de verre, fibres et métal.', 'Baoulé', 'Centre', 'Fin XIXe – début XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1971.297/1971.297_web.jpg', 'https://clevelandart.org/art/1971.297', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1971.297 · titre original : Figure Pair (asye usu)', true, 1),
  ('cma-112585', 'Statuette masculine du « Maître de Totokro »', 'Statue', 'Présentée comme la plus ancienne œuvre connue d''un sculpteur baoulé surnommé le « Maître de Totokro » par les historiens de l''art, d''après la région d''où viennent ses œuvres. Ce type de statuette va d''habitude par paire, homme et femme, et sert aux devins de pont entre le monde des esprits (asye usu) et celui des humains. Chez les Baoulé, le nom du sculpteur n''est pas toujours rendu public.', 'Baoulé', 'Centre', 'Avant 1931', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', 'Conservé dans les réserves du musée (non exposé en ce moment)', 'https://openaccess-cdn.clevelandart.org/1931.204/1931.204_web.jpg', 'https://clevelandart.org/art/1931.204', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1931.204 · titre original : Male Figure', true, 2),
  ('cma-147842', 'Masque portrait mblo', 'Masque', 'Très appréciés des Baoulé, les masques mblo, masculins ou féminins, sortent lors de danses de divertissement. Avec leur coiffure travaillée et leurs fines scarifications, ils sont vus comme les portraits de personnes connues. Ils réunissent les canons de la beauté baoulé : peau lustrée (bonne santé), front haut (intelligence) et yeux baissés (admiration). Ce masque pourrait représenter une aînée respectée. Bois et peinture.', 'Baoulé', 'Centre', 'Début – milieu du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1974.203/1974.203_web.jpg', 'https://clevelandart.org/art/1974.203', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1974.203 · titre original : Portrait Mask (mblo)', true, 3),
  ('cma-148156', 'Masque kplé kplé de la danse goli', 'Masque', 'Le kplé kplé ouvre la danse goli, où quatre paires de masques se succèdent. Dans chaque paire, le masque masculin danse en premier. Portés par de jeunes garçons, ces masques exécutent une danse rapide en frappant le sol. Le kplé kplé masculin est peint en rouge, le féminin, comme celui-ci, en noir. Le danseur tenait le masque en mordant une corde fixée à l''arrière.', 'Baoulé', 'Centre', 'Fin XIXe – début XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1975.155/1975.155_web.jpg', 'https://clevelandart.org/art/1975.155', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1975.155 · titre original : Mask (Kple Kple or Kouassi Gbe)', true, 4),
  ('cma-132047', 'Pendentif en or : visage', 'Bijou', 'Coulé en or selon la technique de la cire perdue. Chez les Baoulé, les objets en or sont les seules œuvres liées aux esprits des ancêtres. Gardés dans des valises ou des jarres, ces ornements (aja) sont sortis lors des grandes occasions comme les funérailles, où on les dispose autour du défunt en signe de respect. Les visages seraient des portraits idéalisés d''amis ou d''êtres aimés ; celui-ci représente un homme barbu à la coiffure élaborée.', 'Baoulé', 'Centre', 'XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108C (bijoux et métal d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1954.602/1954.602_web.jpg', 'https://clevelandart.org/art/1954.602', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1954.602 · titre original : Pendant: Face', true, 5),
  ('cma-129836', 'Pendentif en or : crocodile', 'Bijou', 'Pendentif coulé en or à la cire perdue. L''orfèvre a façonné de très fins rouleaux de cire pour obtenir cette texture. Ces bijoux, liés aux esprits des ancêtres, sont sortis lors des funérailles ; une veuve peut les porter au cou ou dans les cheveux à la cérémonie qui marque la fin du deuil.', 'Baoulé', 'Centre', '1930 ou avant', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108C (bijoux et métal d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1952.265/1952.265_web.jpg', 'https://clevelandart.org/art/1952.265', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1952.265 · titre original : Pendant: Crocodile', true, 6),
  ('cma-130310', 'Pendentif en or au front marqué « ngwa »', 'Bijou', 'Pendentif en or coulé à la cire perdue. La scarification en forme de croissant sur le front s''appelle ngwa, la « lune ». Gardés à l''abri, ces ornements liés aux ancêtres sont exposés lors des grandes occasions comme les funérailles.', 'Baoulé', 'Centre', 'XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108C (bijoux et métal d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1952.85/1952.85_web.jpg', 'https://clevelandart.org/art/1952.85', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1952.85 · titre original : Pendant', true, 7),
  ('cma-146116', 'Poulie de métier à tisser à masque', 'Objet du quotidien', 'La poulie fait partie du métier à tisser les bandes étroites : elle soutient et sépare les fils. Placée au-dessus du tisserand, elle lui offre un bel objet à regarder pendant son travail. Celle-ci représente un masque Bo Nun Amuin, un masque redouté qui évoque les esprits de la nature, utilisé ici de façon profane. Bois, métal et fibres.', 'Baoulé', 'Centre', 'XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', 'Conservé dans les réserves du musée (non exposé en ce moment)', 'https://openaccess-cdn.clevelandart.org/1971.300/1971.300_web.jpg', 'https://clevelandart.org/art/1971.300', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1971.300 · titre original : Heddle Pulley (Bo Nun Amuin mask)', true, 8),
  ('cma-146930', 'Masque dan « coureur »', 'Masque', 'Chez les Dan, le nom d''un masque dépend de son usage et de son costume. Avec son front haut, de style dan du nord, celui-ci pourrait être un masque sagbwe ou gunyege. Comme « masque coureur », il prenait part à des courses organisées le dimanche en saison sèche ; comme « gardien du feu », il protégeait le village des incendies quand soufflait l''harmattan. Il portait autrefois une coiffure en fibres.', 'Dan', 'Ouest (et Liberia)', 'Probablement début du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1972.331/1972.331_web.jpg', 'https://clevelandart.org/art/1972.331', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1972.331 · titre original : Face Mask', true, 9),
  ('cma-171079', 'Cuillère cérémonielle wunkirmian', 'Objet du quotidien', 'Signe de grand prestige, cette cuillère à forme humaine appartenait à une femme mariée reconnue pour ses talents de cultivatrice, sa générosité et son hospitalité. Elle organisait une grande fête du mérite où, avec d''autres femmes respectées, elle préparait à manger pour de nombreux invités. Pendant la fête, les femmes dansaient en brandissant leurs cuillères remplies de riz.', 'Dan', 'Ouest', 'Fin XIXe ou début XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', 'Conservé dans les réserves du musée (non exposé en ce moment)', 'https://openaccess-cdn.clevelandart.org/2013.52/2013.52_web.jpg', 'https://clevelandart.org/art/2013.52', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 2013.52 · titre original : Ceremonial Ladle (Wunkirmian or Wakemia)', true, 10),
  ('cma-136656', 'Maternité sénoufo', 'Statue', 'Au-delà d''une mère qui allaite, cette sculpture évoque la maternité des ancêtres, centrale dans la société sénoufo où l''héritage se transmet par les femmes. Pour certains Sénoufo, la Grande Mère (Katyeleeo ou Maleeo) nourrit les jeunes initiés du « lait du savoir » qui fait d''eux des adultes. Les zones sombres du bois viennent des huiles versées en offrande et pour le protéger.', 'Sénoufo', 'Nord (région de Korhogo)', 'XIXe – XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1961.198/1961.198_web.jpg', 'https://clevelandart.org/art/1961.198', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1961.198 · titre original : Nursing Woman with Child', true, 11),
  ('cma-148153', 'Casque sénoufo du passage à l''âge adulte', 'Masque', 'Ce casque était porté lors des rituels marquant le passage d''un garçon d''une classe d''âge à la suivante, avant son initiation au Poro. Les cornes rappelleraient celles des bœufs, image des jeunes non initiés. La figure féminine évoque les pouvoirs des femmes, qui veillent sur les membres du Poro. Cauris et plumes le décoraient autrefois.', 'Sénoufo', 'Nord', 'Début – milieu du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1975.152/1975.152_web.jpg', 'https://clevelandart.org/art/1975.152', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1975.152 · titre original : Helmet Mask', true, 12),
  ('cma-147843', 'Oiseau-trophée du concours de culture', 'Statue', 'Cet aigle en vol surmontait un long bâton remis au vainqueur d''un concours de culture à la houe entre jeunes hommes. La compétition renforce la solidarité du groupe et célèbre la fertilité. L''oiseau est aussi exposé aux funérailles d''un ancien champion ou d''un membre de sa famille.', 'Sénoufo', 'Nord', 'Début – milieu du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', 'Conservé dans les réserves du musée (non exposé en ce moment)', 'https://openaccess-cdn.clevelandart.org/1974.204/1974.204_web.jpg', 'https://clevelandart.org/art/1974.204', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1974.204 · titre original : Bird Standard', true, 13),
  ('cma-146107', 'Masque wè (tehe gla)', 'Masque', 'Les yeux tubulaires et la frange de crocs de léopard sculptés indiquent un masque masculin. Il n''apparaissait que lors des moments les plus importants : le danseur portait une peau de léopard, tenait une défense d''éléphant et avait le visage peint en blanc. Ces masques faisaient la paix, menaient les guerriers au combat et rendaient la justice.', 'Wè', 'Ouest (et Liberia)', 'Début du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1971.294/1971.294_web.jpg', 'https://clevelandart.org/art/1971.294', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1971.294 · titre original : Face Mask (Tehe gla)', true, 14),
  ('cma-146109', 'Masque éléphant yaouré', 'Masque', 'Le centre de la Côte d''Ivoire est une terre d''échanges entre cultures, visible dans les masques qui mêlent traits humains et animaux. L''éléphant y revient souvent. Chez les Yaouré, les masques éléphants sont liés au culte Dye et apparaissent lorsque d''importants sacrifices doivent être faits. Le sculpteur a réduit la taille des oreilles et des défenses.', 'Yaouré (attribution possible)', 'Centre', 'Début du XXe siècle', 'The Cleveland Museum of Art', 'Cleveland (États-Unis)', '11150 East Boulevard, Cleveland, Ohio · salle 108A (arts d''Afrique)', 'https://openaccess-cdn.clevelandart.org/1971.296/1971.296_web.jpg', 'https://clevelandart.org/art/1971.296', 'The Cleveland Museum of Art, Open Access CC0 · n° d''inventaire 1971.296 · titre original : Face Mask', true, 15)
