-- Bibliothèque : 15 œuvres ivoiriennes du Cleveland Museum of Art (Open Access, CC0).
-- Images et données libres de droits ; descriptions résumées en français depuis les notices du musée.
-- À lancer dans l'éditeur SQL de Supabase, après 0004_bibliotheque_evenements.sql.
-- Relançable sans risque : une œuvre déjà présente est mise à jour.

on conflict (id) do update set title = excluded.title, kind = excluded.kind, description = excluded.description, people = excluded.people, region = excluded.region, period = excluded.period, museum = excluded.museum, city = excluded.city, address = excluded.address, image_url = excluded.image_url, link = excluded.link, source = excluded.source, published = excluded.published, sort = excluded.sort;
